\label{theo:constrained_permutation} Consider optimization problem \eqref{eq:lsq} and for positive integers $m$, 
denote $\nu_m = \E_{g \sim N(0, I_m)}[\nnorm{g}_2] \in \left[\frac{m}{(m+1)^{1/2}}, \; m^{1/2} \right]$ and let $\varepsilon \in (0,1/2)$ be a number such that 
\begin{equation}\label{eq:cond_samples_unrelaxed}
\nu_{n-d} - \frac{\varepsilon}{1-\varepsilon}\nu_n \geq \frac{2}{1 - \varepsilon} w(\mc{T}). 
\end{equation}
If furthermore $n > 9 \vee 4d$, then with probability $\geq 1 - \frac{7}{2}\exp(-c_{\varepsilon} n) - 2 \exp \left(-\frac{1}{2} (d \vee \log n) \right)$,  
\begin{equation}\label{eq:bound_samples_unrelaxed}
\nnorm{\wh{\beta} - \beta^*}_2 \leq   \frac{\sigma}{1 - \sqrt{\frac{4 d \vee \log n}{n}}} \left(\sqrt{\frac{5 (d \vee \log n)}{n}} + \frac{2 (1 + \sqrt{2}) \varepsilon^{-2} \{w(\mc{T}) \vee \log n\}}{\sqrt{n}} \right).
\end{equation}

Specifically, let us fix $\varepsilon = 1/4$ and $d = \alpha n$ for $\alpha \in (0,\frac{1}{4})$, then \eqref{eq:cond_samples_unrelaxed} essentially evaluates as
\begin{equation*}
n \geq \left(\frac{8}{3 (\sqrt{1 -\alpha} - 1/3)}\right)^2 w^2(\mc{T}). 
\end{equation*}

