  \p \left(\sup_{\Delta \in \mc{T}} |\nscp{\texttt{P}_X^{\perp}\boldsymbol{\epsilon}}{\Delta}| > \E\left[\sup_{\Delta \in \mc{T}}  |\nscp{\texttt{P}_X^{\perp}\boldsymbol{\epsilon}}{\Delta}| \;\; \Big|  \texttt{P}_X^{\perp} \right] +  \tau \;\;\Big| \texttt{P}_X^{\perp} \right) \\
