Consider optimization problem \eqref{eq:relax_2} with solution $(\wt{\beta}, \wt{e})$. Then, if $n \geq d$, with probability one
\begin{align*}
  \wt{e} \in \argmin_{e} \frac{1}{n} \nnorm{\emph{\texttt{P}}_X^{\perp} (\mathbf{y} - \sqrt{n}  e)}_2^2 + \lambda \nnorm{e}_1, \quad
  \wt{\beta} \in \Bigg\{ &\left(\frac{X^{\T} X}{n} \right)^{-1} \frac{X^{\T} (\mathbf{y} - \sqrt{n} \wt{e})}{n}, \\
  &\wt{e} \in \argmin_{e} \frac{1}{n} \nnorm{\emph{\texttt{P}}_X^{\perp} (\mathbf{y} - \sqrt{n} e)}_2^2 + \lambda \nnorm{e}_1 \Big \}.
\end{align*}

\label{lem:bound_e} Under the conditions of Theorem \ref{theo:relaxation}, with probability at least $1 - 2 \exp(-c_{\varepsilon} (n-d))  - 2n^{-M^2}$, we have 
\begin{equation*}
\nnorm{\wt{e} - e^*}_2 \leq   48 (1 + M) \sigma  \frac{n}{n-d} \varepsilon^{-1} \sqrt{\frac{k \log n}{n}}.  
\end{equation*}

 We first decompose
\begin{equation*}
  \texttt{P}_X^{\perp} \mathbf{y} = \texttt{P}_X^{\perp} (X \beta^* + \sqrt{n} e^* + \boldsymbol{\epsilon}) = \texttt{P}_X^{\perp} \sqrt{n} e^*  + \wt{\boldsymbol{\epsilon}}, \quad
  \wt{\boldsymbol{\epsilon}} \coloneq \texttt{P}_X^{\perp} \boldsymbol{\epsilon}.  
\end{equation*}
According to Lemma \ref{lem:decoupling_LAD}, since $\wt{e}$ is a minimizer, we have that
\begin{equation*}
  \frac{1}{n} \nnorm{\texttt{P}_X^{\perp} \sqrt{n}   (e^* - \wt{e}) + \wt{\boldsymbol{\epsilon}}}_2^2 + \lambda \nnorm{\wt{e}}_1 \leq
  \frac{1}{n} \nnorm{\wt{\boldsymbol{\epsilon}}}_2^2  + \lambda \nnorm{e^*}_1. 
\end{equation*}
Expanding the square on the left-hand side and re-arranging terms, we obtain that
\begin{equation}\label{eq:lasso_basic}
\frac{1}{n} \nnorm{\texttt{P}_X^{\perp} \sqrt{n}   (e^* - \wt{e})}_2^2 + \lambda \nnorm{\wt{e}}_1 \leq 2 |\scp{e^* - \wt{e}}{\wt{\boldsymbol{\epsilon}}/\sqrt{n}}| + \lambda \nnorm{e^*}_1, 
\end{equation}
which implies
\begin{equation*}
 \lambda \nnorm{\wt{e}}_1 \leq 2 \nnorm{e^* - \wt{e}}_{1} \nnorm{\wt{\boldsymbol{\epsilon}}/\sqrt{n}}_{\infty} + \lambda \nnorm{e^*}_1,
\end{equation*}
and in turn
\begin{align*}
  \lambda \nnorm{\wt{e}_{(S^*)^c} - e_{(S^*)^c}^*}_1 = \lambda \nnorm{\wt{e}_{(S^*)^c}}_1 &\leq 2 \nnorm{e^* - \wt{e}}_{1} \nnorm{\wt{\boldsymbol{\epsilon}}/\sqrt{n}}_{\infty} + \lambda (\nnorm{e^*}_1 - \nnorm{\wt{e}_{S^*}}_1) \\
  &\leq  2 \nnorm{e^* - \wt{e}}_{1} \underbrace{\nnorm{\wt{\boldsymbol{\epsilon}}/\sqrt{n}}_{\infty}}_{\invcoloneq \lambda_0} + \lambda \nnorm{e_{S^*}^*- \wt{e}_{S^*}}_1. 
\end{align*}
Re-arranging, we arrive at 
\begin{equation*}
(\lambda - 2\lambda_0) \nnorm{\wt{e}_{(S^*)^c} - e_{(S^*)^c}^*}_1 \leq (\lambda + 2 \lambda_0) \nnorm{e_{S^*}^*- \wt{e}_{S^*}}_1. 
\end{equation*}
Conditional on the event $\Lambda =\{\lambda \geq 4 \lambda_0 \}$, we hence have that
\begin{equation}\label{eq:cone_condition}
  \nnorm{\wt{e}_{(S^*)^c} - e_{(S^*)^c}^*}_1 \leq 3 \nnorm{\wt{e}_{S^*} - e_{S^*}^*}_1.
\end{equation}
\noindent Equipped with this is intermediate result, we go back to \eqref{eq:lasso_basic}. We first
obtain by re-arranging that 
\begin{align*}
  \frac{1}{n} \nnorm{\texttt{P}_X^{\perp} \sqrt{n}   (e^* - \wt{e})}_2^2 &\leq (2 \lambda_0 + \lambda) \nnorm{\wt{e} - e^*}_1 \\
  &\leq (2 \lambda_0 + \lambda) 4 \nnorm{\wt{e}_{S^*} - e_{S^*}^*}_1 \\
  &\leq (2 \lambda_0 + \lambda) 4 \sqrt{k} \nnorm{\wt{e}_{S^*} - e_{S^*}^*}_2, 
\end{align*}
where we have used \eqref{eq:cone_condition} in the second inequality.  
In order to lower bound the left hand side, note that \eqref{eq:cone_condition} can be written as
$\wt{e} - e^* \in \mc{C}(S^*, 3)$ according to \eqref{eq:lassocone}. Conditional on the event in Lemma
\ref{lem:RE},
\begin{equation*}
\frac{1}{n} \nnorm{\texttt{P}_X^{\perp} \sqrt{n}   (e^* - \wt{e})}_2^2 \geq  \varepsilon \frac{n-d}{n}  \nnorm{e^* - \wt{e}}_2^2.
\end{equation*}
Combining this with the previous display, we find that
\begin{equation*}
 \nnorm{e^* - \wt{e}}_2 \leq 12  \varepsilon^{-1} \frac{n}{n-d} \lambda \sqrt{k}. 
\end{equation*}
\noindent In view of Lemma \ref{lem:maximalgaussian}, the choice $\lambda = 4 (1 + M) \sigma \sqrt{2 \log(n) / n}$ for $M \geq 0$
guarantees that the event $\Lambda$ defined above \eqref{eq:cone_condition} occurs with probability at least $1 - 2n^{-M^2}$.
This completes the proof of the Lemma.

\label{lem:up}
Let $\gamma, \delta > 0$. Consider the event 
\begin{equation}\label{eq:Agamma}
\mathcal{A}_{\gamma}= \left\{\min_{i<j}(\mathbf{x}_i^\top\beta^*-\mathbf{x}_j^\top\beta^*)^2\le \gamma^2 \right\}.
\end{equation}
Then $\p\left( \mathcal{A}_{\gamma}\right)< \delta$ if 
\[
\nnorm{\beta^*}_2^2>\dfrac{n^2(n-1)^2}{4\delta^2\pi}\gamma^2.
\]

It is clear that $\mathcal{A}_{\gamma}\subseteq\bigcup_{i<j}\left\{(\mathbf{x}_i^\top\beta^*-\mathbf{x}_j^\top\beta^*)^2\le \gamma^2 \right\}$. Using the fact that $\mathbf{x}_i^\top\beta^*-\mathbf{x}_j^\top\beta^*\sim N(0,2\|\beta^*\|_2^2)$, we have
\begin{align*}
	\p\left(\mathcal{A}_{\gamma}\right)&\le\p\left(\bigcup_{i<j}\left\{-\dfrac{\gamma}{\sqrt{2}\|\beta^*\|_2}\le (\mathbf{x}_i -\mathbf{x}_j)^\top\dfrac{\beta^*}{\sqrt{2}\|\beta^*\|_2}\le \dfrac{\gamma}{\sqrt{2}\|\beta^*\|_2}\right\}\right)	\\
	&\le \sum_{i<j}\p\left( -\dfrac{\gamma}{\sqrt{2}\|\beta^*\|_2} \le g \leq \dfrac{\gamma}{\sqrt{2}\|\beta^*\|_2} \right), \quad g \sim N(0,1)\\
	&\le\dfrac{n(n-1)}{2} \dfrac{\gamma}{\|\beta^*\|_2\sqrt{\pi}} \quad \text{by Lemma \ref{lem:smallball} in Appendix \ref{app:aux}.}
\end{align*}
Thus, it suffices to require that $\dfrac{n(n-1)}{2} \dfrac{\gamma}{\|\beta^*\|_2\sqrt{\pi}}<\delta$. Resolving for $\nnorm{\beta^*}_2$, this condition becomes
\[
\|\beta^*\|_2^2>\dfrac{n^2(n-1)^2}{4\delta^2\pi}\gamma^2.
\]

\begin{align*}
	\p\left(\mathcal{A}_{\gamma}\right)&\le\p\left(\bigcup_{i<j}\left\{-\dfrac{\gamma}{\sqrt{2}\|\beta^*\|_2}\le (\mathbf{x}_i -\mathbf{x}_j)^\top\dfrac{\beta^*}{\sqrt{2}\|\beta^*\|_2}\le \dfrac{\gamma}{\sqrt{2}\|\beta^*\|_2}\right\}\right)	\\
	&\le \sum_{i<j}\p\left( -\dfrac{\gamma}{\sqrt{2}\|\beta^*\|_2} \le g \leq \dfrac{\gamma}{\sqrt{2}\|\beta^*\|_2} \right), \quad g \sim N(0,1)\\
	&\le\dfrac{n(n-1)}{2} \dfrac{\gamma}{\|\beta^*\|_2\sqrt{\pi}} \quad \text{by Lemma \ref{lem:smallball} in Appendix \ref{app:aux}.}
\end{align*}

\label{lem:fixed}
Conditional on $X$, we have $\p \left(\widehat{\Pi}(\beta^*) \ne \Pi^*\mid X \right)<\delta$ if
\begin{equation}\label{eq:fix}
\min_{i<j}\left(\mathbf{x}_i^\top\beta^*-\mathbf{x}_j^\top\beta^*\right)^2>4\sigma^2\log\dfrac{n(n-1)}{\delta}.
\end{equation}

 Without loss of generality, we may assume that $\Pi^* = I_n$. By construction of $\widehat{\Pi}(\beta^*)$, it is clear
  that $\widehat{\Pi}(\beta^*) \ne \Pi^*$ whenever there exists $i\ne j$ such that $(y_i-y_j)(\mathbf{x}_i^\top\beta^*-\mathbf{x}_j^\top\beta^*)<0$, that is, the order between $\mathbf{x}_i^\top\beta^*$ and $\mathbf{x}_j^\top\beta^*$ is different than that of $y_i, y_j$. First, conditioning on the random design matrix $X$,  we have
\begin{align*}
\p(\wh{\Pi}(\beta^*)\ne \Pi^* \mid X)&=2\p\left(\bigcup_{i<j}\left\{y_i-y_j>0 \mid \mathbf{x}_i^\top\beta^*-\mathbf{x}_j^\top\beta^*<0\right\}\right)\\\
&\le 2 \sum_{i<j}\p\left(y_i-y_j>0 \mid \mathbf{x}_i^\top\beta^*-\mathbf{x}_j^\top\beta^*<0\right)
\end{align*}
 Since $y_i-y_j\mid \mathbf{x}_i^\top\beta^*-\mathbf{x}_j^\top\beta^*\sim N(\mathbf{x}_i^\top\beta^*-\mathbf{x}_j^\top\beta^*, 2\sigma^2)$, using the usual tail bound for the Gaussian distribution for each term in the above sum, we obtain
 \begin{align*}
\p(\wh{\Pi}(\beta^*)\ne \Pi^* \mid X)&\le 2\sum_{i<j} \exp\left( -\dfrac{\left(\mathbf{x}_i^\top\beta^*-\mathbf{x}_j^\top\beta^*\right)^2}{4\sigma^2} \right)\\
&\le n(n-1)\exp\left( -\dfrac{\min_{i<j}\left(\mathbf{x}_i^\top\beta^*-\mathbf{x}_j^\top\beta^*\right)^2}{4\sigma^2} \right).
\end{align*}
Hence, for any $\delta>0$, $\p(\wh{\Pi}(\beta^*)\ne \Pi^* \mid X) <\delta$ if

\begin{equation*}
\min_{i<j}\left(\mathbf{x}_i^\top\beta^*-\mathbf{x}_j^\top\beta^*\right)^2>4\sigma^2\log\dfrac{n(n-1)}{\delta}.
\end{equation*}

\label{lem:low}
Consider the event $\mc{A}_{\gamma}$ in \eqref{eq:Agamma}. Then, for all $n \geq 5$, $\p\left( \mathcal{A}_{\gamma}\right)\ge 0.85$ if 
\begin{equation}\label{eq:lb}
\|\beta^*\|_2^2\le \dfrac{1}{25\pi}n^2\gamma^2.
\end{equation}

\cite{CandesTao2005} Let $A \in \mathbb{R}^{N \times p}$ and $B_0(s;p) = \{v \in \mathbb{R}^p: \; \nnorm{v}_0 \leq s \}$. Define the $s$-sparse minimum and maximum eigenvalues associated with $A$ by 
\begin{equation*}
  \lambda_{\min}(s) = \min_{v \in B_0(s;p) \setminus \{0\}} \frac{\nnorm{A v}_2^2}{\nnorm{v}_2^2}, \qquad
  \lambda_{\max}(s) = \max_{v \in B_0(s;p) \setminus \{0\}} \frac{\nnorm{A v}_2^2}{\nnorm{v}_2^2}. 
\end{equation*}
Let $\delta \in (0,1)$. We say that $A$ is an ($s$, $\delta$)-\textbf{restricted isometry}  if
\begin{equation*}
  1 - \delta \leq \lambda_{\min}(s) \leq \lambda_{\max}(s) \leq 1+\delta.
\end{equation*}

\cite{Bickel2009} Let $A \in \mathbb{R}^{N \times p}$. We define the $(s, \alpha)$-\textbf{restricted eigenvalue} by 
\begin{equation}\label{eq:recondition}
\phi(s, \alpha) = \min_{J \in \mc{J}(s)} \, \min_{v \in \mc{C}(J, \alpha) \setminus
  0}\, \, \frac{\nnorm{A v}_2^2}{\nnorm{v_J}_2^2}. 
\end{equation}

\cite{Baraniuk2006}
Let $A$ be a random of matrix of size $N \times p$ satisfying 
\begin{equation}\label{eq:normpreservation}
 \p((1 - \varepsilon) \nnorm{v}_2^2 \leq \nnorm{A v}_2^2 \leq (1 + \varepsilon) \nnorm{v}_2^2) \leq 2 \exp(-N c_0(\varepsilon))
\end{equation}
for any $\varepsilon \in (0,1)$ and any $v \in \mathbb{R}^p$, where $c_0(\varepsilon) > 0$ is a constant depending only on $\varepsilon$. Then for any $\delta \in (0,1)$, there exist constants $c_1, c_2 > 0$ depending only on $\delta$ such that $A$ is a $(q, \delta)$-restricted isometry for any $q \leq c_1 N / \log(p/q)$ with probability at least $1 - 2 \exp(-c_2 N)$.

\label{lem:DasGupta}(from Lemma 2.2 in \cite{DasGupta2003})
  Let $\emph{\texttt{P}}$ denote the orthogonal projection on an $N$-dimensional subspace of $\mathbb{R}^p$ chosen uniformly at
  random from the Grassmannian $\textsf{G}(p, N)$. Then, for any $v \in \mathbb{R}^p$ and any $\varepsilon \in (0,1)$,
  \begin{equation*}
    \p \left((1 - \varepsilon) \nnorm{v}_2^2 \leq \frac{p}{N} \norm{\emph{\texttt{P}} v}_2^2 \leq (1 + \varepsilon) \nnorm{v}_2^2 \right) \leq 2 \exp(-N  (\varepsilon^2/4 - \varepsilon^3/6) \})
  \end{equation*}

: the lemma is essentially implied by the fact that under the stated conditions, the matrix $\texttt{P}_{X}^{\perp}$ has its $(k,3)$-restricted eigenvalue bounded away from zero by a constant $\varepsilon$ as to be shown below. "Essentially" refers to the fact that it can be shown (cf.~\cite{Zhou2009}) that a matrix $A$ with restricted eigenvalue $\phi(k,3)$ obeys
\begin{equation*}
\nnorm{A v}_2^2 \geq \frac{1}{32} \phi(k,3) \nnorm{v}_2^2 \qquad \forall v \in \bigcup_{J \in \mc{J}(k)} \mc{C}(J,3). 
\end{equation*}  
As sketched above, a lower bound on $\phi(k,3)$ follows if $A$ is a $(3k, \delta^*/4)$ restricted isometry for some $\delta^* \in (0,1)$. That property is in turn satisfied with high probability if $A$ satisfies \eqref{eq:normpreservation}. Applying Lemma \ref{lem:DasGupta} with 
$\texttt{P} = \texttt{P}_{X}^{\perp}$, $p = n$ and $N = n-d$ yields the conclusion.

\label{lem:concentration_width}\emph{(\textbf{Concentration of Gaussian processes \cite{Boucheron2013}})}
Let $K$ be a closed subset of the unit sphere in $\mathbb{R}^m$ with Gaussian width $w(K)$, and let $g \sim N(0, I_m)$. Then for all $t > 0$
 \begin{equation*}
 \p \left(\sup_{x \in K} |\scp{g}{x}| \geq w(K) + t \right) \leq \exp(-t^2/2). 
\end{equation*}

\label{lem:extremesingularvalues}\hspace*{-.7ex}\emph{(\textbf{Concentration of extreme singular values of Gaussian matrices \cite{Vershynin2010}})}\\
  Let $X$ be an $n \times d$ Gaussian matrix with i.i.d.~$N(0,1)$-entries. Denote by $\sigma_{\min}(X)$
  and $\sigma_{\max}(X)$ the minimum respectively maximum singular value of $X$. Then for any $t > 0$
\begin{equation*}
\p(\sigma_{\min}(X) \geq \sqrt{n} - \sqrt{d} - t) \leq \exp(-t^2 / 2), \qquad \p(\sigma_{\max}(X) \geq \sqrt{n} + \sqrt{d} + t) \leq \exp(-t^2 / 2).  
\end{equation*}

\label{lem:hansonwright}\emph{(\textbf{Concentration of quadratic forms \cite{Hsu2012}})}\\
Let $A$ be a an $m \times n$ matrix, $\Gamma = A^{\T} A$, and $g \sim N(0, I_n)$. Then for all $t > 0$
\begin{equation*}
  \p(\nnorm{A g}_2^2  > \mathrm{tr}(\Gamma) + 2 \sqrt{\mathrm{tr}(\Gamma^2) t} + 2 \nnorm{\Gamma}_2 t) \leq \exp(-t). 
\end{equation*}
